def weakestRoad(n, roads):
    parent = list(range(n + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b, w in roads:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    if find(1) != find(n):
        return -1
    root = find(1)
    return min(w for a, b, w in roads if find(a) == root)
